# Garantias: transferência não pode ser implementada por income/expense artificial.
for need in ['CREATE TABLE IF NOT EXISTS wallet_transactions','transaction_type TEXT NOT NULL','source_wallet','destination_wallet','walletPersonalBalanceCents','walletSharedBalanceCents','/api/wallet/transfers','Transferir para o casal','Destino da entrada','Pagar com','reportsPage','walletOverviewHtml']:
    target=sql if need.startswith('CREATE TABLE') or need.startswith('transaction_type') or need in ['source_wallet','destination_wallet'] else (w if need in ['walletPersonalBalanceCents','walletSharedBalanceCents','/api/wallet/transfers'] else a)
    if need not in target:raise SystemExit('Carteiras: marcador ausente '+need)
if "INSERT INTO incomes" in wallet_routes or "INSERT INTO shared_incomes" in wallet_routes or "INSERT INTO expenses" in wallet_routes or "INSERT INTO shared_expenses" in wallet_routes:
    raise SystemExit('Carteiras: transferência não pode criar receita/despesa artificial')

schema.write_text(sql);worker.write_text(w);app.write_text(a);cssp.write_text(css)
print('Ritmo V1: carteiras pessoais/casal, transferência real, histórico, relatórios e listas compactas aplicados.')
